/* One guild workspace. All actions remain browser-local design demonstrations. */
state.guildTeam=state.guildTeam||{};const teamUI={query:''};
function teamConfig(id){return state.guildTeam[id]||{pin:null,copying:{enabled:false,source:'leader'}}}
function teamOwner(id){return state.membership?.id===id&&state.membership.role==='owner'}
function teamProvider(g,policy=teamConfig(g.id).copying){if(!policy?.enabled)return null;if(policy.source==='leader'){let c=captains.find(c=>c.guild===g.id&&c.providerRole!=='Analyst');if(!c){c={...captains[0],id:'guild-leader-'+g.id,guild:g.id,name:'Guild Leader',roi:0,drawdown:0,winRate:0,trades:0,copiers:0,days:0,providerRole:'Leader',style:'Guild leader · Sample strategy'};captains.push(c)}return c}const personKey=Array.from(policy.analystName||'').reduce((h,c)=>Math.imul(h^c.charCodeAt(0),16777619)>>>0,2166136261).toString(16);const id='guild-analyst-'+g.id+'-'+personKey;let c=leaderById(id);if(!c){c={...captains[0],id,guild:g.id,name:policy.analystName||'Guild Analyst',roi:0,drawdown:0,winRate:0,trades:0,copiers:0,days:0,providerRole:'Analyst',style:'Analyst · Sample strategy',description:'A role-based strategy provided by the guild. No live performance or order execution is connected.'};captains.push(c)}c.name=policy.analystName||'Guild Analyst';return c}
for(const id of Object.keys(state.guildTeam)){const g=guildById(id);if(g&&teamConfig(id).copying?.enabled)teamProvider(g)}
const teamCopyBase=canCopyGuildLeader;
canCopyGuildLeader=function(c){return !!c&&teamCopyBase(c)&&!!teamConfig(c.guild).copying?.enabled&&teamProvider(guildById(c.guild))?.id===c.id};
const teamCopyGateBase=showGuildCopyGate;showGuildCopyGate=function(c){if(c&&state.membership?.id===c.guild&&state.membership.role==='member'&&!canCopyGuildLeader(c)){open(`<h2>Guild copying is not available for this strategy.</h2><p>Your guild leader controls which Leader or Analyst strategy is open. Your membership does not activate copying automatically.</p><button class="secondary" data-close-flow>Back to the guild</button>`);return}teamCopyGateBase(c)};
const teamSetupBase=renderCopySetup;renderCopySetup=function(){teamSetupBase();const c=copyDraft&&leaderById(copyDraft.leader),label=$('#modal-content .copy-target small');if(label&&c)label.textContent=guildById(c.guild).name+' · '+(c.providerRole||'Leader')};
function teamHeader(g,{preview=false,settings=false}={}){return `<header class="team-identity"><div><img class="team-guild-pfp" src="${emblem(g)}" alt="${escapeHtml(g.name)}"><span><small>${preview?'SAMPLE MEMBER VIEW':'YOUR GUILD'}${communityById(g.id)?.city?' · '+escapeHtml(communityById(g.id).city):''}</small><h1>${escapeHtml(g.name)}</h1>${guildRankChip(g)}</span></div><div class="team-header-actions"><span class="team-role">${preview?'Member preview':state.membership?.role==='owner'?'Guild Leader':'Member'}</span><button class="primary" data-flow-trade>Go to trade ${arrow()}</button>${!preview?`<details class="team-admin-menu"><summary aria-label="Guild options">•••</summary><div>${teamOwner(g.id)?link('competition/entry','Team event entry'):''}${link('my-guild/settings','Membership settings')}</div></details>`:''}</div></header>`}
function teamMatch(g,preview=false){const r=preview?{stage:'matched',trades:[],round:1}:journeyRecord(g),isNew=g.isNew&&r.stage==='prepare',op=isNew?null:battleOpponent(g),active=['live','review','final'].includes(r.stage),total=active?matchTotals(g,r):{team:0,opponent:0},share=active?total.team/(total.team+total.opponent)*100:50;return `<section class="team-match-banner"><div class="team-match-top"><span>${icon('swords')} ${r.stage==='live'?'CURRENT GUILD BATTLE':r.stage==='review'?'MATCH RESULT UNDER REVIEW':r.stage==='final'?'LAST MATCH RESULT':'NEXT GUILD BATTLE'}</span><span class="demo-chip">${isNew?'AWAITING MATCHMAKING':'SAMPLE '+(active?r.stage.toUpperCase():'FIXTURE')}</span></div><div class="team-match-teams"><div><img src="${emblem(g)}" alt=""><span><small>YOUR GUILD</small><h2>${escapeHtml(g.name)}</h2>${guildRankChip(g)}<strong>${active?compactMoney(total.team):'—'}</strong></span></div><span class="team-vs">VS</span><div class="team-opponent">${op?`<span><small>THE OPPONENT</small><h2>${escapeHtml(op.name)}</h2>${guildRankChip(op)}<strong>${active?compactMoney(total.opponent):'—'}</strong></span><img src="${emblem(op)}" alt="">`:'<span><small>THE OPPONENT</small><h2>To be announced</h2><p>Your first match will appear here.</p></span>'}</div></div><div class="team-match-score"><div><span>${active?share.toFixed(1)+'%':'Match has not started'}</span><span>${active?(100-share).toFixed(1)+'%':'Start time to be announced'}</span></div><div class="team-match-track ${active?'':'is-upcoming'}"><i style="width:${share}%"></i></div></div><div class="team-match-bottom"><span>${active?'Sample volume gap · '+compactMoney(Math.abs(total.team-total.opponent)):'Pairing, schedule and scoring are illustrative; final event rules will follow.'}</span><button class="text-button" data-team-match-rules>Match rules ${arrow()}</button></div></section>`}
function teamPinned(g,preview=false){const pin=teamConfig(g.id).pin,text=pin?.text||g.announcement||'Review the match briefing, share your market views in team chat and keep to your own trading limits. The team’s progress and your contribution are shown below.';return `<section class="team-pin-panel"><div class="team-panel-heading"><h2>${icon('pin')} From your guild leader</h2>${!preview&&teamOwner(g.id)?'<button class="text-button" data-team-pin>Edit message</button>':''}</div><p>${escapeHtml(text).replace(/\n/g,'<br>')}</p><div><span>${pin?'Pinned by '+escapeHtml(pin.author):'Sample team briefing · Not a live instruction'}</span><button class="secondary" ${preview?'disabled':'data-open-chat="'+g.id+'"'}>${icon('chat')} Team chat</button></div></section>`}
function teamDashboard(g,preview=false){const r=preview?{trades:[]}:journeyRecord(g),personal=r.trades.reduce((n,t)=>n+t.notional,0);return `<section class="team-dashboard"><div class="team-panel-heading"><h2>Team dashboard</h2><span>SAMPLE TEAM DATA</span></div><div class="team-stat-grid"><div><small>TEAM SEASON VOLUME</small><strong>${numberCompact(seasonVolume(g))}</strong><span>Illustrative eligible activity</span></div><div><small>GUILD MEMBERS</small><strong>${g.members.toLocaleString()}</strong><span>No member limit</span></div><div><small>YOUR ROUND CONTRIBUTION</small><strong>${compactMoney(personal)}</strong><span>${r.trades.length} simulated records</span></div><div><small>YOUR CONTRIBUTION STATUS</small><strong>${r.trades.length?'Recorded':'No activity yet'}</strong><span>No live trade feed connected</span></div></div></section>`}
function teamObjectives(g,preview=false){const r=preview?{briefed:false,trades:[]}:journeyRecord(g),checked=state.checkins[g.id]===new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Hong_Kong'});return `<section class="team-objectives"><div class="team-panel-heading"><h2>Team objectives</h2><span>PARTICIPATION PREVIEW</span></div><div><span><strong>Read the match briefing</strong><small>Understand the format, attribution and your own trading decisions.</small></span><button class="secondary" data-team-brief ${preview?'disabled':''}>${r.briefed?'Reviewed':'Read briefing'}</button></div><div><span><strong>Trade & track your contribution</strong><small>${r.trades.length?r.trades.length+' simulated records in this round.':'Eligible trade attribution will appear when trading is connected.'}</small></span><span class="team-objective-status">${r.trades.length?'Recorded · demo':'Trading not connected'}</span></div><div><span><strong>Let the team know you’re here</strong><small>Local check-in only; no points or rewards are granted.</small></span><button class="secondary" data-mission-action="checkin" data-context-guild="${g.id}" ${preview||checked?'disabled':''}>${checked?'Checked in':'Check in'}</button></div></section>`}
function teamCopyPanel(g,preview=false){const policy=teamConfig(g.id).copying,c=policy?.enabled?teamProvider(g):null,plan=state.copyPlans.find(p=>p.leader===c?.id&&p.status!=='stopped');return `<section class="team-copy-panel"><div class="team-panel-heading"><h2>Guild copying</h2>${!preview&&teamOwner(g.id)?'<button class="secondary" data-team-policy>Manage availability</button>':''}</div>${!c?`<div class="team-copy-closed">${icon('lock')}<div><strong>Copying is not enabled by the guild leader.</strong><p>The guild leader can open a Leader or Analyst strategy for members. Participation never requires copying.</p></div></div>`:`<div class="team-copy-provider"><span class="captain-avatar ${c.color}">${escapeHtml(c.name.slice(0,1))}</span><div><small>${c.providerRole||'Leader'} · SAMPLE STRATEGY</small><h3>${escapeHtml(c.name)}</h3><p>Members choose their own allocation and limits. No orders are executed here.</p></div>${!preview&&canCopyGuildLeader(c)?`<button class="primary" data-start-copy="${c.id}">${plan?'Review my plan':'Set up copying'} ${icon('copy')}</button>`:'<span class="team-role">'+(preview?'Members only':'Provider access')+'</span>'}</div>${plan?`<div class="team-inline-plan"><span>YOUR LOCAL PLAN · ${plan.status.toUpperCase()} · ${numberCompact(Number(plan.allocation))}</span><div><button class="secondary" data-plan-toggle="${plan.id}">${plan.status==='running'?'Pause':'Resume'}</button><button class="text-button" data-plan-stop="${plan.id}">Stop</button></div></div>`:''}<p class="team-copy-note">Illustrative strategy. Copying can lose capital. Guild availability and member activation are separate choices.</p>`}</section>`}
function teamMemberRows(g,preview=false){const policy=teamConfig(g.id).copying,rows=roster(g).map(m=>({...m,role:policy?.source==='analyst'&&policy.analystName===m.name?'Analyst':m.role})).filter(m=>m.name.toLowerCase().includes(teamUI.query.toLowerCase())).sort((a,b)=>b.volume-a.volume);return rows.map((m,i)=>`<tr class="${m.isYou&&!preview?'is-you':''}"><td>${i+1}</td><td><span class="team-member-name"><span class="avatar avatar-${i%4}">${escapeHtml(m.initial)}</span><span>${escapeHtml(m.name)}${m.isYou&&!preview?'<small>YOU</small>':''}</span></span></td><td>${escapeHtml(m.role)}</td><td>${compactMoney(m.volume)}</td><td>${m.isYou&&!preview?'Local profile':'Sample profile'}</td></tr>`).join('')||'<tr><td colspan="5">No members match your search.</td></tr>'}
function teamMembers(g,preview=false){return `<section class="team-members-panel" id="team-members"><div class="team-panel-heading"><div><h2>Members</h2><p>${g.members.toLocaleString()} members · Sample roster shown below</p></div><label class="search">${icon('search')}<input type="search" id="team-member-search" value="${escapeHtml(teamUI.query)}" placeholder="Search members…" aria-label="Search guild members"></label></div><div class="team-roster-scroll"><table><thead><tr><th>#</th><th>Member</th><th>Role</th><th>14D volume · sample</th><th>Profile</th></tr></thead><tbody id="team-member-body">${teamMemberRows(g,preview)}</tbody></table></div></section>`}
const teamRailPositionBase=climbPersonalPosition;climbPersonalPosition=function(){const html=teamRailPositionBase();return routePath?html.replace('href="#find-community" data-find-community','href="#/discover"'):html};
function teamWorkspace(g,{preview=false,settings=false}={}){return `<div class="team-workspace" data-team-guild="${g.id}" data-team-preview="${preview}">${climbMobileBoard()}<div class="climb-shell"><div class="team-workspace-main">${teamHeader(g,{preview,settings})}${preview?'<div class="team-demo-note">Read-only sample member view. Your actual membership is unchanged.</div>':'<div class="team-demo-note">Local design preview · Sample fixtures and statistics · No live registration, orders or rewards.</div>'}${settings?settingsPage(g,false):teamMatch(g,preview)+teamPinned(g,preview)+teamDashboard(g,preview)+teamObjectives(g,preview)+teamCopyPanel(g,preview)+teamMembers(g,preview)}</div>${climbRail()}</div></div>`}
const teamLegacyMyGuild=myGuildPage;myGuildPage=function(tab='overview',preview=false){const g=preview?guildById('huddle'):state.membership&&guildById(state.membership.id);if(!g)return teamLegacyMyGuild(tab,preview);return teamWorkspace(g,{preview,settings:tab==='settings'&&!preview})};
const teamPublicGuild=guildPage;guildPage=function(id,tab='overview'){const g=guildById(id);if(!g)return teamPublicGuild(id,tab);if(state.membership?.id===id)return teamWorkspace(g);let html=teamPublicGuild(id,tab);const box=document.createElement('div');box.innerHTML=html;box.querySelectorAll('a[href="#/rankings"]').forEach(e=>e.remove());return `<div class="team-public-visit">${climbMobileBoard()}<div class="climb-shell"><div>${box.innerHTML}</div>${climbRail()}</div></div>`};
function activeTeam(){const el=$('#workspace .team-workspace');return el?{g:guildById(el.dataset.teamGuild),preview:el.dataset.teamPreview==='true'}:null}
function teamManagePolicy(g){if(!teamOwner(g.id))return;const policy=teamConfig(g.id).copying||{},options=roster(g).filter(m=>m.role!=='Leader'&&!m.isYou);open(`<span class="page-eyebrow">GUILD LEADER CONTROLS · LOCAL DEMO</span><h2>Choose who your team can copy.</h2><form id="team-policy-form" class="form" data-guild="${g.id}"><label class="check"><input name="enabled" type="checkbox" ${policy.enabled?'checked':''}><span>Make a strategy available to guild members</span></label><label for="team-copy-source">Strategy provider role</label><select id="team-copy-source" name="source"><option value="leader" ${policy.source!=='analyst'?'selected':''}>Guild Leader</option><option value="analyst" ${policy.source==='analyst'?'selected':''}>Analyst</option></select><label for="team-analyst">Analyst · choose a sample member</label><select id="team-analyst" name="analyst"><option value="">Select a member</option>${options.map(m=>`<option value="${escapeHtml(m.name)}" ${policy.analystName===m.name?'selected':''}>${escapeHtml(m.name)}</option>`).join('')}</select><p>Availability does not activate anyone’s plan. Existing plans pause if the selected provider changes or copying closes.</p><button class="primary" type="submit">Save availability</button></form>`)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const ctx=activeTeam();if(!ctx)return;const {g}=ctx;if(ctx.preview&&!b.hasAttribute('data-team-match-rules'))return;if(b.hasAttribute('data-team-policy'))teamManagePolicy(g);if(b.hasAttribute('data-team-pin')&&teamOwner(g.id)){const pin=teamConfig(g.id).pin;open(`<span class="page-eyebrow">GUILD LEADER · PINNED MESSAGE</span><h2>Set the team’s direction.</h2><form id="team-pin-form" class="form" data-guild="${g.id}"><label for="team-pin-text">Message for your guild</label><textarea id="team-pin-text" name="text" rows="5" required maxlength="1000">${escapeHtml(pin?.text||g.announcement||'')}</textarea><button class="primary" type="submit">Pin message</button></form>`)}if(b.hasAttribute('data-team-brief'))openBriefing();if(b.hasAttribute('data-team-match-rules'))open(`<h2>Guild Battle · Sample format</h2><p>Two guilds compete within a round. The guild season leaderboard remains a separate competition view.</p><p>Current sample totals use notional volume. Match timing, eligibility, rewards and progression conditions will be defined separately.</p><button class="secondary" data-close-flow>Back to the guild</button>`)});
document.addEventListener('input',e=>{if(e.target.id!=='team-member-search')return;teamUI.query=e.target.value;const ctx=activeTeam();if(ctx)$('#team-member-body').innerHTML=teamMemberRows(ctx.g,ctx.preview)});
document.addEventListener('submit',e=>{if(!['team-pin-form','team-policy-form'].includes(e.target.id))return;e.preventDefault();const f=e.target,g=guildById(f.dataset.guild);if(!g||!teamOwner(g.id)||!f.reportValidity())return;const data=new FormData(f),cfg=state.guildTeam[g.id]||(state.guildTeam[g.id]={pin:null,copying:{enabled:false,source:'leader'}});if(f.id==='team-pin-form'){const text=String(data.get('text')||'').trim();if(!text)return;cfg.pin={text:text.slice(0,1000),author:state.membership.name||'Guild Leader',at:new Date().toISOString()}}else{const enabled=data.has('enabled'),source=data.get('source'),analystName=String(data.get('analyst')||'');if(!['leader','analyst'].includes(source))return;if(enabled&&source==='analyst'&&!roster(g).some(m=>m.name===analystName&&m.role!=='Leader'&&!m.isYou)){toast('Choose an Analyst from the sample roster.');return}cfg.copying={enabled,source,analystName};if(enabled)teamProvider(g,cfg.copying);for(const plan of state.copyPlans){const c=leaderById(plan.leader);if(c?.guild===g.id&&plan.status==='running'&&(!enabled||teamProvider(g)?.id!==plan.leader)){plan.status='paused';plan.pauseReason='guild-policy'}}}modal.close();save();renderRoute(false);toast(f.id==='team-pin-form'?'Pinned message saved locally.':'Guild copying availability saved. Member plans are not activated.')});
document.addEventListener('click',e=>{if(e.target.closest('[data-open-copy-plans]')){modal.close();renderRoute(false)}},true);
const teamBaseRender=renderRoute;renderRoute=function(scroll=true){teamBaseRender(scroll);const root=$('#workspace .team-workspace');if(root&&routePath==='my-guild'){document.title=(guildById(root.dataset.teamGuild)?.name||'My Guild')+' — Team workspace'}};
renderRoute(false);
